"""Aggregate the fixed-roughness stabilization tests, including whole-wave metrics."""
from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import broad_study as b
from audit_current_predictor import DIAG,window_pair
r=b.OUT/'investigation';out=r/'stabilized48'
results=[json.loads(p.read_text()) for p in sorted(out.glob('dx*/result.json'))];assert len(results)==13,len(results)
base=pd.read_parquet(out/'dx100_theta0.7_cfl0.35/wave.parquet');population=pd.read_parquet(DIAG);population=population[population.example.astype(str).eq('48')];window=population.iloc[0];start=pd.Timestamp(window.onset_utc).timestamp();end=pd.Timestamp(window.end_utc).timestamp();comparisons=[]
for x in results:
 w=pd.read_parquet(Path(x['folder'])/'wave.parquet');metric=window_pair(base,w,start,end,window.baseline_cms);diff=(w.q_outlet_cms-base.q_outlet_cms).to_numpy();mask=(w.time_utc.astype('int64')/1e9>=start)&(w.time_utc.astype('int64')/1e9<=end);metric.update(tag=x['tag'],rmse_cms=float(np.sqrt(np.mean(diff[mask]**2))),max_abs_difference_cms=float(max(abs(diff[mask]))));comparisons.append(metric)
lookup={x['tag']:x for x in results};mlookup={x['tag']:x for x in comparisons};b.save(out/'wave_comparison.json',dict(reference='dx100_theta0.7_cfl0.35',onset_utc=str(window.onset_utc),end_utc=str(window.end_utc),baseline_cms=float(window.baseline_cms),comparisons=comparisons));b.save(out/'all_results.json',results)
fig=make_subplots(rows=2,cols=2,subplot_titles=['50 m: effect of weighting θ (CFL 0.35)','Refining to 25 m: spikes return','50 m: timestep sensitivity near the crest','Uniform reach 161 analogue: one-hour disturbance growth'],vertical_spacing=.16,horizontal_spacing=.1)
mc=pd.read_parquet(r/'current_mc/states/48/S000_base/outlet.parquet')
def add(w,name,color,row,col,dash='solid',show=True):
 z=w[(w.time_utc>=pd.Timestamp(window.onset_utc)-pd.Timedelta(hours=5))&(w.time_utc<=pd.Timestamp(window.end_utc)+pd.Timedelta(hours=10))];indices={0,len(z)-1};q=z.q_outlet_cms.to_numpy()
 for i in range(0,len(z),5):indices.update([i+int(np.argmin(q[i:i+5])),i+int(np.argmax(q[i:i+5]))])
 z=z.iloc[sorted(indices)];fig.add_trace(go.Scatter(x=z.time_utc,y=z.q_outlet_cms,name=name,line=dict(color=color,dash=dash),legendgroup=name,showlegend=show),row=row,col=col)
for row,col in [(1,1),(1,2),(2,1)]:
 add(mc,'Current MC','#777777',row,col,'dash',row==1 and col==1);add(base,'100 m, θ=0.7','#111111',row,col,'solid',row==1 and col==1)
for theta,color in [(.9,'#D55E00'),(.8,'#CC79A7'),(.7,'#0072B2')]:add(pd.read_parquet(out/f'dx50_theta{theta:g}_cfl0.35/wave.parquet'),f'50 m, θ={theta:g}, CFL 0.35',color,1,1)
for tag,name,color,dash in [('dx25_theta0.8_cfl0.35','25 m, θ=0.8, CFL 0.35','#CC79A7','solid'),('dx25_theta0.7_cfl0.35','25 m, θ=0.7, CFL 0.35','#D55E00','solid'),('dx25_theta0.7_cfl0.175','25 m, θ=0.7, CFL 0.175','#009E73','dot')]:add(pd.read_parquet(out/tag/'wave.parquet'),name,color,1,2,dash)
for theta,color in [(.7,'#0072B2'),(.8,'#CC79A7')]:
 for cfl,dash in [(.35,'solid'),(.175,'dot')]:add(pd.read_parquet(out/f'dx50_theta{theta:g}_cfl{cfl:g}/wave.parquet'),f'50 m, θ={theta:g}, CFL {cfl:g}',color,2,1,dash,cfl==.175)
modes=pd.DataFrame(json.loads((out/'uniform_results.json').read_text()))
for theta,color in [(1.,'#999999'),(.9,'#D55E00'),(.8,'#CC79A7'),(.7,'#0072B2')]:
 z=modes[(modes.reach==161)&(modes.dt==3)&(modes.theta==theta)].sort_values('dx');fig.add_trace(go.Scatter(x=z.dx,y=z.observed_amplification,name=f'Uniform test θ={theta:g}',mode='lines+markers',line=dict(color=color)),row=2,col=2)
fig.add_hline(y=1,line_dash='dash',line_color='gray',row=2,col=2)
for row,col in [(1,1),(1,2),(2,1)]:fig.update_yaxes(title_text='Discharge (m³/s)',row=row,col=col);fig.update_xaxes(title_text='UTC',row=row,col=col)
fig.update_yaxes(range=[260,325],row=2,col=1);fig.update_xaxes(title_text='Cell length (m)',row=2,col=2);fig.update_yaxes(title_text='Amplitude / initial amplitude',row=2,col=2)
fig.update_layout(template='plotly_white',height=1100,width=1500,title='Example 48: q-centred stabilisation helps, but grid convergence is not established',legend=dict(orientation='h',y=-.22),margin=dict(b=230),hovermode='x unified')
fig.write_html(out/'stabilized_plotly.html',include_plotlyjs=True);(out/'plot_expected.json').write_text(json.dumps(dict(traces=len(fig.data),subplots=4)))
lines=['Example 48: documented q-centred stabilization — diagnostic experiment','', 'Outcome: substantially improved 50 m behaviour, but no demonstrated grid convergence. Do not promote these runs into the calibrated broad-study results.','', 'METHOD AND SCOPE','Manning n remains 0.020799605931143154. Measured widths, bed proxies, forcing, physical topology and normal-flow outlet remain fixed. Theta is a numerical weighting, not a calibrated physical parameter. Each case is re-equilibrated before the event. Original-network cases only; no collapses in this focused solver test.','The momentum numerator uses qbar = theta*q[j] + (1-theta)/2*(q[left]+q[right]), evaluated from the OLD face flows simultaneously. Friction uses the original local old q, not qbar. Pressure gradient, critical cap and conservative donor-volume limiter remain unchanged.','The published regular-grid q-centred formulation is applied only where three consecutive faces lie within the same physical reach with equal widths and face distances. Physical reach boundaries/junctions use theta=1. This is our explicit network adaptation; it is not the official LISFLOOD-FP executable, nor a validated general junction extension. Smoothed faces: 941/1522 at 100 m, 2272/2887 at 50 m, 4998/5623 at 25 m.','Primary source: de Almeida et al. (2012), https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2011WR011570','Equation independently checked against the published form reproduced in Deltares Wflow documentation (2D overland section, NOT its 1D river scheme): https://deltares.github.io/Wflow.jl/v0.7.3/model_docs/lateral/local-inertial/','', 'VERIFICATION','Theta=1 gives bit-for-bit identical outputs to the conservative baseline. One q-centred step matches independent vectorized arithmetic. Uniform Manning equilibrium and lake-at-rest checks pass. 72 periodic uniform-channel mode tests match independently derived linear growth factors within 0.1% (actual differences much smaller). These checks establish implementation consistency, not full hydraulic accuracy.','', 'NETWORK RESULTS','Grid m | theta | CFL | feature height m3/s | feature error min | max depth m | positivity face-steps | relative mass residual']
for x in results:
 a=x['audit'];lines.append(f"{x['length']:3} | {x['theta']:.1f} | {x['cfl']:.3f} | {x['feature_height_cms']:.3f} | {x['timing_error_minutes']:+.1f} | {a['maximum_depth_m']:.4f} | {a['positivity_limited_face_steps']:.0f} | {x['relative_mass_residual']:.3g}")
lines+=['','All event clipping volumes are zero. Conserving volume is necessary but is not a sufficient validity criterion. Finite peaks in the 25 m oscillatory runs are not credible calibration targets. Theta 0.7 was the strongest damping in the preset 0.9/0.8/0.7 trial set; it was not fitted to the gauge.','', 'WHOLE-WAVE CHECK (common existing MC 0.5% event window, constant baseline; no clipping of excess discharge)','Reference: 100 m theta=.7 CFL=.35. Centroids are not reported when the curve dips below baseline in this window. Peak timing changes are not interpreted as a rigid translation of the whole wave.']
for x in comparisons:
 cent=x['centroid_minutes'];ct=f'{cent:+.4f} min' if np.isfinite(cent) else 'undefined: below-baseline excursions'
 lines.append(f"{x['tag']}: centroid difference {ct}; RMSE {x['rmse_cms']:.4f} m3/s; max absolute difference {x['max_abs_difference_cms']:.4f} m3/s.")
a=mlookup['dx50_theta0.7_cfl0.175'];z=mlookup['dx50_theta0.7_cfl0.35'];lines+=['',f"For 50 m theta=.7, halving CFL changes peak selection by 40 min but changes the common-window centroid by only {(a['centroid_minutes']-z['centroid_minutes'])*60:+.3f} seconds. Thus the bulk timing is much less sensitive than the crest maximum. Smaller ripples/crest reshaping still prevent treating peak calibration as robust.",'The nominal matched-diffusion control (theta=.8, CFL=.35 versus theta=.9, CFL=.175) gives the same +207.5 min selected-peak error and similar heights (~318 m3/s). This supports sensitivity to numerical damping, rather than timestep accuracy alone. Holding theta fixed while reducing dt increases smoothing per simulated second. The matching is nominal, not exact, since the friction denominator also depends on dt.','', 'UNIFORM CHANNEL MECHANISM','For the uniform analogue of reach 161, at 50 m and dt=3 s, one-hour amplitude factor falls from 1.563 (theta=1) to 1.314 (theta=.7), but remains above 1. Growth is reduced, not eliminated. This test contains no junctions, outlet, wetting/drying or cap activity. It demonstrates that unresolved growing modes are not exclusively a junction treatment problem. It does not uniquely partition the complete network error.','', 'DECISION','Do not choose theta by matching the downstream gauge, and do not recalibrate this variant yet. Retain the original production code and mark these results experimental. A defensible next comparison is an independent full shallow-water reference on straight-channel benchmarks with the same h, slope and roughness, followed by a junction benchmark. Additional diffusion may suppress a symptom without establishing that the simplified equations are appropriate for these hydraulics. No full shallow-water solver benchmark was run in this test.']
(out/'findings.txt').write_text('\n'.join(lines)+'\n')
files=['inertial_stabilized_diagnostic_kernel.py','run_stabilized48.py','uniform_stabilized48.py','test_stabilized_diagnostic.py','report_stabilized48.py'];(out/'source_manifest.json').write_text(json.dumps({p:hashlib.sha256((Path(__file__).parent/p).read_bytes()).hexdigest() for p in files},indent=2))
print(out/'stabilized_plotly.html');print('runs',len(results),'traces',len(fig.data))
